package com.fifotech.task.controller;
import com.fifotech.task.domain.*;import com.fifotech.task.dto.ApiDtos.*;import com.fifotech.task.service.TaskService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController {private final TaskService tasks;public TaskController(TaskService tasks){this.tasks=tasks;}@PostMapping @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public TaskResponse create(@Valid @RequestBody TaskRequest r,@AuthenticationPrincipal User actor){return tasks.create(r,actor);}@GetMapping public List<TaskResponse> list(@AuthenticationPrincipal User actor,@RequestParam(required=false) TaskStatus status,@RequestParam(required=false) Priority priority,@RequestParam(required=false) Long assigneeId){return tasks.list(actor,status,priority,assigneeId);}@GetMapping("/{id}") public TaskResponse get(@PathVariable Long id,@AuthenticationPrincipal User actor){return tasks.get(id,actor);}@PutMapping("/{id}/status") @PreAuthorize("hasRole('EMPLOYEE')") public TaskResponse status(@PathVariable Long id,@Valid @RequestBody StatusRequest r,@AuthenticationPrincipal User actor){return tasks.updateStatus(id,r.status(),actor);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public TaskResponse update(@PathVariable Long id,@Valid @RequestBody TaskRequest r,@AuthenticationPrincipal User actor){return tasks.update(id,r,actor);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){tasks.delete(id);}}
